#include "ftebroom_plugin_projection.h"
static std::vector<float> pluginColoredLines,pluginBoxes,pluginLabelPositions;
static std::vector<uint32_t> pluginLineColors,pluginBoxColors;
static std::vector<std::string> pluginLabels;
static bool pluginViewportCapture=false,pluginViewportAllowed=false,pluginViewportBlocked=false;
static std::string pluginCurrentId,pluginCaptureOwner;
static int pluginButtonsDown=0,pluginButtonsPressed=0,pluginButtonsReleased=0;
static uint32_t pluginDigitKeys=0;
static bool pluginCoordinates(const float* p,size_t count){if(!p)return false;for(size_t i=0;i<count;i++)if(!std::isfinite(p[i])||std::abs(p[i])>131072)return false;return true;}
static void pluginColoredPreview(const float* xyz,const uint32_t* colors,size_t n){pluginColoredLines.clear();pluginLineColors.clear();if(!xyz||!colors||n>16384||!pluginCoordinates(xyz,n*6))return;pluginColoredLines.assign(xyz,xyz+n*6);pluginLineColors.assign(colors,colors+n);}
static void pluginBoxPreview(const float* xyz,const uint32_t* colors,size_t n){pluginBoxes.clear();pluginBoxColors.clear();if(!xyz||!colors||n>32768||!pluginCoordinates(xyz,n*6))return;for(size_t i=0;i<n;i++)for(int a=0;a<3;a++)if(xyz[i*6+a]>xyz[i*6+3+a])return;pluginBoxes.assign(xyz,xyz+n*6);pluginBoxColors.assign(colors,colors+n);}
static void pluginLabelPreview(const float* xyz,const char* const* labels,size_t n){pluginLabelPositions.clear();pluginLabels.clear();if(!xyz||!labels||n>4096||!pluginCoordinates(xyz,n*3))return;for(size_t i=0;i<n;i++)if(!labels[i]||std::strlen(labels[i])>1024)return;pluginLabelPositions.assign(xyz,xyz+n*3);for(size_t i=0;i<n;i++)pluginLabels.emplace_back(labels[i]);}
static void pluginViewportRelease(bool escape=false){pluginViewportCapture=false;pluginCaptureOwner.clear();pluginViewportBlocked=escape;pluginButtonsDown=pluginButtonsPressed=pluginButtonsReleased=0;}
static void pluginPreviewClear(){pluginPreviewLines.clear();pluginColoredLines.clear();pluginLineColors.clear();pluginBoxes.clear();pluginBoxColors.clear();pluginLabels.clear();pluginLabelPositions.clear();pluginViewportRelease();}
static int pluginCaptureViewport(int enable){if(!enable){if(pluginCaptureOwner.empty()||pluginCaptureOwner==pluginCurrentId)pluginViewportRelease();return 1;}if(!pluginViewportAllowed||pluginCurrentId.empty()||pluginViewportBlocked||modEmbedded||cvars->GetFloat("ftebroom_bsp_preview"))return 0;if(!pluginCaptureOwner.empty()&&pluginCaptureOwner!=pluginCurrentId)return 0;pluginCaptureOwner=pluginCurrentId;pluginViewportCapture=true;return 1;}
static bool pluginProjection(int view,rbviewport::Projection& p){auto rect=viewRects[view];if(rect.w<1||rect.h<1)return false;p.x=rect.x;p.y=rect.y;p.w=rect.w;p.h=rect.h;p.type=rect.type;char state[512]{};cvars->GetString("ftebroom_camera_state",state,sizeof state);float v[7];if(!cameraParse(state,v))return false;p.origin={v[0],v[1],v[2]};p.fov=v[6];float pitch=v[3]*.01745329252f,yaw=v[4]*.01745329252f;p.forward={std::cos(pitch)*std::cos(yaw),std::cos(pitch)*std::sin(yaw),-std::sin(pitch)};p.right={std::sin(yaw),-std::cos(yaw),0};p.up={std::sin(pitch)*std::cos(yaw),std::sin(pitch)*std::sin(yaw),std::cos(pitch)};
 if(rect.type){std::string data;float x,y,z;if(!qcQuery(5,rect.type,data)||std::sscanf(data.c_str(),"RBVIEW1 %f %f %f",&x,&y,&z)!=3)return false;p.origin={x,y,z};p.span=std::clamp(cvars->GetFloat("ca_brush_viewsize"),1.f,262144.f);if(rect.type==3){p.right={1,0,0};p.up={0,1,0};p.forward={0,0,-1};}else if(rect.type==2){p.right={1,0,0};p.up={0,0,1};p.forward={0,1,0};}else{p.right={0,1,0};p.up={0,0,1};p.forward={-1,0,0};}}return true;}
static int pluginViewportState(RBViewportStateV1* out){if(!pluginViewportAllowed||!out||out->struct_size<sizeof(RBViewportStateV1)||modEmbedded||cvars->GetFloat("ftebroom_bsp_preview"))return 0;auto mouse=ImGui::GetIO().MousePos;int hit=viewHit(mouse.x,mouse.y);if(hit<0)hit=viewFocus;rbviewport::Projection p;if(!pluginProjection(hit,p))return 0;out->hovered=viewHit(mouse.x,mouse.y)>=0&&!ImGui::GetIO().WantCaptureMouse&&!popupOpen&&!uiBlocksScene(mouse.x,mouse.y);out->view_type=p.type==3?1:p.type==2?2:p.type==1?3:0;rbviewport::V start,ray;p.ray(mouse.x,mouse.y,start,ray);std::copy(start.begin(),start.end(),out->ray_origin);std::copy(ray.begin(),ray.end(),out->ray_dir);std::copy(p.origin.begin(),p.origin.end(),out->camera_pos);std::copy(p.forward.begin(),p.forward.end(),out->camera_forward);out->buttons_down=pluginButtonsDown;out->buttons_pressed=pluginButtonsPressed;out->buttons_released=pluginButtonsReleased;out->modifiers=(shiftHeld?1:0)|(ctrlHeld?2:0)|(altHeld?4:0);out->digit_keys=pluginDigitKeys;return 1;}
static int pluginSelectionBounds(float* out){if(!out)return 0;std::string data;return qcQuery(6,0,data)&&std::sscanf(data.c_str(),"RBBOUNDS1 %f %f %f %f %f %f",out,out+1,out+2,out+3,out+4,out+5)==6&&pluginCoordinates(out,6);}
static void pluginViewportDraw(){if(pluginPreviewLines.empty()&&pluginColoredLines.empty()&&pluginBoxes.empty()&&pluginLabels.empty()&&!pluginViewportCapture)return;if(modEmbedded||cvars->GetFloat("ftebroom_bsp_preview"))return;auto draw=ImGui::GetForegroundDrawList();for(int view=0;view<viewLayout;view++){rbviewport::Projection projection;if(!pluginProjection(view,projection))continue;auto rect=viewRects[view];draw->PushClipRect({rect.x,rect.y},{rect.x+rect.w,rect.y+rect.h},true);auto project=[&](const float* p,ImVec2& pixel){return projection.project({p[0],p[1],p[2]},pixel.x,pixel.y);};
 for(size_t i=0;i<pluginPreviewLines.size();i+=6){ImVec2 a,b;if(project(&pluginPreviewLines[i],a)&&project(&pluginPreviewLines[i+3],b))draw->AddLine(a,b,IM_COL32(99,232,143,220),1.5f);}
 for(size_t i=0;i<pluginLineColors.size();i++){ImVec2 a,b;if(project(&pluginColoredLines[i*6],a)&&project(&pluginColoredLines[i*6+3],b))draw->AddLine(a,b,pluginLineColors[i],1.5f);}
 std::vector<size_t> boxes(pluginBoxColors.size());for(size_t i=0;i<boxes.size();i++)boxes[i]=i;auto depth=[&](size_t i){float n=0;for(int a=0;a<3;a++)n+=((pluginBoxes[i*6+a]+pluginBoxes[i*6+3+a])*.5f-projection.origin[a])*projection.forward[a];return n;};std::stable_sort(boxes.begin(),boxes.end(),[&](size_t a,size_t b){return depth(a)>depth(b);});
 for(size_t box:boxes){const float* p=&pluginBoxes[box*6];for(int axis=0;axis<3;axis++)for(int side=0;side<2;side++){int u=(axis+1)%3,v=(axis+2)%3;float position=p[axis+(side?3:0)];if(!projection.type&&((side&&projection.origin[axis]<position)||(!side&&projection.origin[axis]>position)))continue;if(projection.type&&projection.forward[axis]*(side?1:-1)>=0)continue;ImVec2 corners[4];bool valid=true;int bits[4]={0,1,3,2};for(int c=0;c<4;c++){float point[3];point[axis]=position;point[u]=p[u+(bits[c]&1?3:0)];point[v]=p[v+(bits[c]&2?3:0)];valid&=project(point,corners[c]);}if(valid)draw->AddConvexPolyFilled(corners,4,pluginBoxColors[box]);}}
 for(size_t i=0;i<pluginLabels.size();i++){ImVec2 p;if(project(&pluginLabelPositions[i*3],p)){draw->AddText({p.x+1,p.y+1},IM_COL32(0,0,0,230),pluginLabels[i].c_str());draw->AddText(p,IM_COL32(245,245,245,255),pluginLabels[i].c_str());}}
 if(pluginViewportCapture)draw->AddText({rect.x+10,rect.y+30},IM_COL32(255,220,100,255),"AutoLevel tool active - Esc to exit");draw->PopClipRect();}}
